> /* ------------------------------------------------------------------ */
/* Variables                                                           */
/* ------------------------------------------------------------------ */

:root {
    --ink: #0f0f0f;
    --ink-soft: #2d2d2d;
    --ink-muted: #6b6b6b;
    --ink-faint: #a0a0a0;
    --paper: #f7f6f3;
    --paper-warm: #f0ede6;
    --paper-card: #ffffff;
    --accent: #1a472a;
    --accent-light: #e8f0eb;
    --accent-2: #c17f24;
    --accent-2-light: #fdf3e3;
    --danger: #c0392b;
    --danger-light: #fdecea;
    --border: #e4e1da;
    --border-soft: #eeebe4;

    --font-display: 'DM Serif Display', Georgia, serif;
    --font-body: 'DM Sans', system-ui, sans-serif;

    --max-width: 1200px;
    --auth-width: 440px;

    --radius-sm: 6px;
    --radius-md: 12px;
    --radius-lg: 20px;
}

/* ------------------------------------------------------------------ */
/* Reset                                                               */
/* ------------------------------------------------------------------ */

*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html { font-size: 16px; scroll-behavior: smooth; }

body {
    background: var(--paper);
    color: var(--ink);
    font-family: var(--font-body);
    font-size: 1rem;
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }

/* ------------------------------------------------------------------ */
/* Navbar                                                              */
/* ------------------------------------------------------------------ */

.navbar {
    position: sticky;
    top: 0;
    z-index: 100;
    background: var(--paper);
    border-bottom: 1px solid var(--border);
    padding: 0 2rem;
}

.nav-inner {
    max-width: var(--max-width);
    margin: 0 auto;
    height: 60px;
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.nav-brand {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-family: var(--font-body);
    font-weight: 600;
    font-size: 1.1rem;
    color: var(--ink);
}

.brand-icon {
    color: var(--accent);
    font-size: 1.3rem;
}

.brand-name { color: var(--ink); }

.nav-links {
    display: flex;
    align-items: center;
    gap: 1.5rem;
    font-size: 0.9rem;
    font-weight: 500;
}

.nav-links a { color: var(--ink-muted); transition: color 0.2s; }
.nav-links a:hover { color: var(--ink); }

.nav-cta {
    background: var(--ink) !important;
    color: var(--paper) !important;
    padding: 0.45rem 1.1rem;
    border-radius: var(--radius-sm);
    transition: background 0.2s !important;
}

.nav-cta:hover { background: var(--accent) !important; }

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

.main-content { min-height: calc(100vh - 60px - 100px); }

/* ------------------------------------------------------------------ */
/* Hero                                                                */
/* ------------------------------------------------------------------ */

.hero {
    padding: 5rem 2rem 4rem;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: center;
    max-width: var(--max-width);
    margin: 0 auto;
}

.hero-inner {
    max-width: 580px;
}

.hero-badge {
    display: inline-block;
    background: #d4f0e8;
    color: #2d6a5a;
    font-size: 0.9rem;
    font-weight: 500;
    padding: 0.5rem 1.25rem;
    border-radius: 999px;
    margin-bottom: 2rem;
}

.badge-dot {
    color: #2d6a5a;
    margin-right: 0.25rem;
}

.hero-title {
    font-family: var(--font-body);
    font-size: clamp(2.75rem, 5.5vw, 4.5rem);
    line-height: 1.1;
    letter-spacing: -0.03em;
    color: var(--ink);
    font-weight: 600;
    margin-bottom: 1.5rem;
}

.hero-title-green {
    color: #4a9d7e;
    font-weight: 600;
}

.hero-subtitle {
    font-size: 1.15rem;
    color: #6b6b6b;
    line-height: 1.6;
    max-width: 520px;
    margin-bottom: 2.5rem;
}

.hero-actions {
    display: flex;
    gap: 1rem;
    align-items: center;
}

/* ------------------------------------------------------------------ */
/* Mock card (hero visual)                                             */
/* ------------------------------------------------------------------ */

.hero-visual {
    display: flex;
    justify-content: center;
}

.mock-card {
    background: #f5f5f5;
    border: 1px solid #e0e0e0;
    border-radius: 16px;
    padding: 1.5rem;
    width: 100%;
    max-width: 520px;
    box-shadow: 0 4px 24px rgba(0,0,0,0.08);
}

.mock-window-controls {
    display: flex;
    gap: 0.5rem;
    margin-bottom: 1.5rem;
}

.window-dot {
    width: 12px;
    height: 12px;
    border-radius: 50%;
}

.window-red { background: #ff5f56; }
.window-yellow { background: #ffbd2e; }
.window-green { background: #27c93f; }

.mock-stats {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1rem;
    margin-bottom: 1.75rem;
}

.stat-card {
    background: white;
    border: 1px solid #e8e8e8;
    border-radius: 10px;
    padding: 1rem;
}

.stat-label {
    font-size: 0.75rem;
    color: #999;
    margin-bottom: 0.35rem;
}

.stat-value {
    font-size: 1.5rem;
    font-weight: 600;
    color: var(--ink);
    margin-bottom: 0.25rem;
}

.stat-change {
    font-size: 0.75rem;
    color: #999;
}

.stat-red { color: #ff6b6b; }
.stat-green { color: #4a9d7e; }

.mock-bars { 
    display: flex; 
    flex-direction: column; 
    gap: 1.25rem;
    background: white;
    border: 1px solid #e8e8e8;
    border-radius: 10px;
    padding: 1.25rem;
}

.mock-bar-row {
    display: grid;
    grid-template-columns: 60px 1fr;
    align-items: center;
    gap: 1rem;
}

.mock-cat {
    font-size: 0.85rem;
    font-weight: 500;
    color: #666;
}

.mock-bar-track {
    height: 10px;
    background: #e8e8e8;
    border-radius: 999px;
    overflow: hidden;
}

.mock-bar {
    height: 100%;
    border-radius: 999px;
    transition: width 0.6s ease;
}

.mock-bar-orange { background: #ffa94d; }
.mock-bar-blue { background: #5b9fd9; }
.mock-bar-purple { background: #9b8bc7; }

/* ------------------------------------------------------------------ */
/* Buttons                                                             */
/* ------------------------------------------------------------------ */

.btn-primary {
    display: inline-block;
    background: var(--ink);
    color: var(--paper);
    padding: 0.8rem 1.75rem;
    border-radius: 8px;
    font-family: var(--font-body);
    font-size: 1rem;
    font-weight: 500;
    cursor: pointer;
    border: none;
    transition: background 0.2s;
    text-decoration: none;
}

.btn-primary:hover { background: #2d2d2d; }

.btn-secondary {
    display: inline-block;
    background: var(--ink);
    color: var(--paper);
    padding: 0.8rem 1.75rem;
    border-radius: 8px;
    font-size: 1rem;
    font-weight: 500;
    transition: all 0.2s;
    text-decoration: none;
}

.btn-secondary:hover {
    background: #2d2d2d;
}

.btn-ghost {
    display: inline-block;
    background: transparent;
    color: var(--ink-soft);
    padding: 0.65rem 1.5rem;
    border-radius: var(--radius-sm);
    font-size: 0.9rem;
    font-weight: 500;
    border: 1px solid var(--border);
    transition: all 0.2s;
    text-decoration: none;
}

.btn-ghost:hover {
    border-color: var(--ink);
    color: var(--ink);
}

/* ------------------------------------------------------------------ */
/* Features section                                                    */
/* ------------------------------------------------------------------ */

.features {
    background: var(--paper-warm);
    border-top: 1px solid var(--border);
    border-bottom: 1px solid var(--border);
    padding: 5rem 2rem;
}

.features-inner {
    max-width: var(--max-width);
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 2rem;
}

.feature-card {
    background: var(--paper-card);
    border: 1px solid var(--border);
    border-radius: var(--radius-md);
    padding: 2rem;
}

.feature-icon {
    font-size: 1.5rem;
    color: var(--accent);
    margin-bottom: 1rem;
    font-weight: 700;
}

.feature-title {
    font-family: var(--font-display);
    font-size: 1.2rem;
    color: var(--ink);
    margin-bottom: 0.75rem;
}

.feature-body {
    font-size: 0.9rem;
    color: var(--ink-muted);
    line-height: 1.7;
}

/* ------------------------------------------------------------------ */
/* CTA section                                                         */
/* ------------------------------------------------------------------ */

.cta-section {
    padding: 6rem 2rem;
    text-align: center;
}

.cta-inner {
    max-width: 560px;
    margin: 0 auto;
}

.cta-title {
    font-family: var(--font-display);
    font-size: clamp(1.75rem, 3vw, 2.5rem);
    color: var(--ink);
    margin-bottom: 1rem;
}

.cta-body {
    font-size: 1rem;
    color: var(--ink-muted);
    margin-bottom: 2rem;
}

/* ------------------------------------------------------------------ */
/* Auth pages                                                          */
/* ------------------------------------------------------------------ */

.auth-section {
    min-height: calc(100vh - 60px - 100px);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 3rem 2rem;
}

.auth-container {
    width: 100%;
    max-width: var(--auth-width);
}

.auth-header {
    text-align: center;
    margin-bottom: 2rem;
}

.auth-title {
    font-family: var(--font-display);
    font-size: 2rem;
    color: var(--ink);
    margin-bottom: 0.5rem;
}

.auth-subtitle {
    font-size: 0.9rem;
    color: var(--ink-muted);
}

.auth-card {
    background: var(--paper-card);
    border: 1px solid var(--border);
    border-radius: var(--radius-md);
    padding: 2rem;
    margin-bottom: 1.5rem;
}

.auth-error {
    background: var(--danger-light);
    color: var(--danger);
    border: 1px solid #f5c6c2;
    border-radius: var(--radius-sm);
    padding: 0.75rem 1rem;
    font-size: 0.875rem;
    margin-bottom: 1.25rem;
}

.form-group { margin-bottom: 1.25rem; }

.form-group label {
    display: block;
    font-size: 0.85rem;
    font-weight: 500;
    color: var(--ink-soft);
    margin-bottom: 0.4rem;
}

.form-input {
    width: 100%;
    padding: 0.6rem 0.875rem;
    border: 1px solid var(--border);
    border-radius: var(--radius-sm);
    font-family: var(--font-body);
    font-size: 0.95rem;
    color: var(--ink);
    background: var(--paper);
    outline: none;
    transition: border-color 0.2s;
}

.form-input:focus { border-color: var(--accent); }

.form-input::placeholder { color: var(--ink-faint); }

.btn-submit {
    width: 100%;
    padding: 0.7rem;
    background: var(--ink);
    color: var(--paper);
    border: none;
    border-radius: var(--radius-sm);
    font-family: var(--font-body);
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.2s;
    margin-top: 0.5rem;
}

.btn-submit:hover { background: var(--accent); }

.auth-switch {
    text-align: center;
    font-size: 0.875rem;
    color: var(--ink-muted);
}

.auth-switch a {
    color: var(--accent);
    font-weight: 500;
}

.auth-switch a:hover { text-decoration: underline; }

/* ------------------------------------------------------------------ */
/* Footer                                                              */
/* ------------------------------------------------------------------ */

.footer {
    background: var(--ink);
    color: var(--paper);
    padding: 2.5rem 2rem;
    text-align: center;
}

.footer-inner {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.4rem;
}

.footer .brand-icon { color: var(--accent-2); font-size: 1.5rem; }

.footer-name {
    font-weight: 600;
    font-size: 1rem;
}

.footer-copy {
    font-size: 0.8rem;
    color: var(--ink-faint);
}

/* ------------------------------------------------------------------ */
/* Responsive                                                          */
/* ------------------------------------------------------------------ */

@media (max-width: 900px) {
    .hero {
        grid-template-columns: 1fr;
        text-align: center;
    }

    .hero-subtitle { max-width: 100%; }
    .hero-actions { justify-content: center; }
    .hero-visual { display: none; }

    .features-inner { grid-template-columns: 1fr; }
}

@media (max-width: 600px) {
    .nav-links a:not(.nav-cta) { display: none; }
    .hero { padding: 3rem 1rem 2rem; }
}


/* ------------------------------------------------------------------ */
/* Legal pages (Terms, Privacy)                                        */
/* ------------------------------------------------------------------ */

.legal-section {
    padding: 4rem 2rem;
    max-width: 780px;
    margin: 0 auto;
}

.legal-header {
    margin-bottom: 2.5rem;
}

.legal-title {
    font-family: var(--font-display);
    font-size: clamp(2rem, 4vw, 2.75rem);
    color: var(--ink);
    margin-bottom: 0.5rem;
}

.legal-updated {
    font-size: 0.85rem;
    color: var(--ink-muted);
}

.legal-body h2 {
    font-family: var(--font-display);
    font-size: 1.25rem;
    color: var(--ink);
    margin-top: 2.25rem;
    margin-bottom: 0.75rem;
}

.legal-body p {
    font-size: 0.95rem;
    color: var(--ink-soft);
    line-height: 1.8;
    margin-bottom: 1rem;
}

.legal-link {
    color: var(--accent);
    font-weight: 500;
}

.legal-link:hover {
    text-decoration: underline;
}

.footer-links {
    margin-top: 0.25rem;
}

.footer-links a {
    font-size: 0.8rem;
    color: var(--ink-faint);
    transition: color 0.2s;
}

.footer-links a:hover {
    color: var(--paper);
}

