    transition: background 0.2s;
    text-decoration: none;
}

.btn-primary:hover { background: #2d2d2d; }

.btn-secondary {
    display: inline-block;
    background: var(--ink);
    color: var(--paper);
    padding: 0.8rem 1.75rem;
    border-radius: 8px;
    font-size: 1rem;
    font-weight: 500;
    transition: all 0.2s;
    text-decoration: none;
}

.btn-secondary:hover {
    background: #2d2d2d;
}

.btn-ghost {
    display: inline-block;
    background: transparent;
    color: var(--ink-soft);
    padding: 0.65rem 1.5rem;
    border-radius: var(--radius-sm);
    font-size: 0.9rem;
    font-weight: 500;
    border: 1px solid var(--border);
    transition: all 0.2s;
    text-decoration: none;
}

.btn-ghost:hover {
    border-color: var(--ink);
    color: var(--ink);
}

/* ------------------------------------------------------------------ */
/* Features section                                                    */
/* ------------------------------------------------------------------ */

.features {
    background: var(--paper-warm);
    border-top: 1px solid var(--border);
    border-bottom: 1px solid var(--border);
    padding: 5rem 2rem;
}

.features-inner {
    max-width: var(--max-width);
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 2rem;
}

.feature-card {
    background: var(--paper-card);
    border: 1px solid var(--border);
    border-radius: var(--radius-md);
    padding: 2rem;
}

.feature-icon {
    font-size: 1.5rem;
    color: var(--accent);
    margin-bottom: 1rem;
    font-weight: 700;
}

.feature-title {
    font-family: var(--font-display);
    font-size: 1.2rem;
    color: var(--ink);
    margin-bottom: 0.75rem;
}

.feature-body {
    font-size: 0.9rem;
    color: var(--ink-muted);
    line-height: 1.7;
}

/* ------------------------------------------------------------------ */
/* CTA section                                                         */
/* ------------------------------------------------------------------ */

.cta-section {
    padding: 6rem 2rem;
    text-align: center;
}

.cta-inner {
    max-width: 560px;
    margin: 0 auto;
}

.cta-title {
    font-family: var(--font-display);
    font-size: clamp(1.75rem, 3vw, 2.5rem);
    color: var(--ink);
    margin-bottom: 1rem;
}

.cta-body {
    font-size: 1rem;
    color: var(--ink-muted);
    margin-bottom: 2rem;
}

/* ------------------------------------------------------------------ */
/* Auth pages                                                          */
/* ------------------------------------------------------------------ */

.auth-section {
    min-height: calc(100vh - 60px - 100px);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 3rem 2rem;
}

.auth-container {
    width: 100%;
    max-width: var(--auth-width);
}

.auth-header {
    text-align: center;
    margin-bottom: 2rem;
}

.auth-title {
    font-family: var(--font-display);
    font-size: 2rem;
    color: var(--ink);
    margin-bottom: 0.5rem;
}

.auth-subtitle {
    font-size: 0.9rem;
    color: var(--ink-muted);
}

.auth-card {
    background: var(--paper-card);
    border: 1px solid var(--border);
    border-radius: var(--radius-md);
    padding: 2rem;
    margin-bottom: 1.5rem;
}

.auth-error {
    background: var(--danger-light);
    color: var(--danger);
    border: 1px solid #f5c6c2;
    border-radius: var(--radius-sm);
    padding: 0.75rem 1rem;
    font-size: 0.875rem;
    margin-bottom: 1.25rem;
}

.form-group { margin-bottom: 1.25rem; }

.form-group label {
    display: block;
    font-size: 0.85rem;
    font-weight: 500;
    color: var(--ink-soft);
    margin-bottom: 0.4rem;
}

.form-input {
    width: 100%;
    padding: 0.6rem 0.875rem;
    border: 1px solid var(--border);
    border-radius: var(--radius-sm);
    font-family: var(--font-body);
    font-size: 0.95rem;
    color: var(--ink);
    background: var(--paper);
    outline: none;
    transition: border-color 0.2s;
}

.form-input:focus { border-color: var(--accent); }

.form-input::placeholder { color: var(--ink-faint); }

.btn-submit {
    width: 100%;
    padding: 0.7rem;
    background: var(--ink);
    color: var(--paper);
    border: none;
    border-radius: var(--radius-sm);
    font-family: var(--font-body);
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.2s;
    margin-top: 0.5rem;
}

.btn-submit:hover { background: var(--accent); }

.auth-switch {
    text-align: center;
    font-size: 0.875rem;
    color: var(--ink-muted);
}

.auth-switch a {
    color: var(--accent);
    font-weight: 500;
}

.auth-switch a:hover { text-decoration: underline; }

/* ------------------------------------------------------------------ */
/* Footer                                                              */
/* ------------------------------------------------------------------ */

.footer {
    background: var(--ink);
    color: var(--paper);
    padding: 2.5rem 2rem;
    text-align: center;
}

.footer-inner {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.4rem;
}

.footer .brand-icon { color: var(--accent-2); font-size: 1.5rem; }

.footer-name {
    font-weight: 600;
    font-size: 1rem;
}

.footer-copy {
    font-size: 0.8rem;
    color: var(--ink-faint);
}

/* ------------------------------------------------------------------ */
/* Responsive                                                          */
/* ------------------------------------------------------------------ */

@media (max-width: 900px) {
    .hero {
        grid-template-columns: 1fr;
        text-align: center;
    }

    .hero-subtitle { max-width: 100%; }
    .hero-actions { justify-content: center; }
    .hero-visual { display: none; }

    .features-inner { grid-template-columns: 1fr; }
}

@media (max-width: 600px) {
    .nav-links a:not(.nav-cta) { display: none; }
    .hero { padding: 3rem 1rem 2rem; }
}


/* ------------------------------------------------------------------ */
/* Legal pages (Terms, Privacy)                                        */
/* ------------------------------------------------------------------ */

.legal-section {
    padding: 4rem 2rem;
    max-width: 780px;
    margin: 0 auto;
}

.legal-header {
    margin-bottom: 2.5rem;
}

.legal-title {
    font-family: var(--font-display);
    font-size: clamp(2rem, 4vw, 2.75rem);
    color: var(--ink);
    margin-bottom: 0.5rem;
}

.legal-updated {
    font-size: 0.85rem;
    color: var(--ink-muted);
}

.legal-body h2 {
    font-family: var(--font-display);
    font-size: 1.25rem;
    color: var(--ink);
    margin-top: 2.25rem;
    margin-bottom: 0.75rem;
}

.legal-body p {
    font-size: 0.95rem;
    color: var(--ink-soft);
    line-height: 1.8;
    margin-bottom: 1rem;
}

.legal-link {
    color: var(--accent);
    font-weight: 500;
}

.legal-link:hover {
    text-decoration: underline;
}

.footer-links {
    margin-top: 0.25rem;
}

.footer-links a {
    font-size: 0.8rem;
    color: var(--ink-faint);
    transition: color 0.2s;
}

.footer-links a:hover {
    color: var(--paper);
}

